//! The public-domain demo project in `demo/`, rendered end to end through the `ib` binary.
//!
//! The demo images are generated by `inbetween_testkit::demo`, so they carry no licence.
//! Regenerate the committed files with:
//! `cargo test -p inbetween-cli --test demo -- --ignored regenerate`

use inbetween_codecs::{decode, encode_png, read_file};
use inbetween_doc::{DotPair, DotSet, ImageRef, OutputSettings, Project, Sequence};
use inbetween_geom::Point;
use inbetween_testkit::demo;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

const W: u32 = 480;
const H: u32 = 360;

fn demo_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../demo")
}

fn demo_project() -> Project {
    let pairs = demo::dot_pairs(W, H)
        .into_iter()
        .map(|((x1, y1), (x2, y2))| DotPair::new(Point::new(x1, y1), Point::new(x2, y2)))
        .collect();
    Project {
        output: OutputSettings {
            width: W,
            height: H,
        },
        sequences: vec![Sequence {
            name: "sun to moon".into(),
            image1: ImageRef::new("sun.png"),
            image2: ImageRef::new("moon.png"),
            dots: DotSet::new(pairs),
            frames: 12,
            ..Sequence::default()
        }],
    }
}

#[test]
#[ignore = "rewrites the committed demo files"]
fn regenerate() {
    let dir = demo_dir();
    std::fs::create_dir_all(&dir).unwrap();
    let (sun, moon) = demo::pair(W, H).unwrap();
    for (name, img) in [("sun.png", sun), ("moon.png", moon)] {
        std::fs::write(dir.join(name), encode_png(W, H, &img.to_rgba8()).unwrap()).unwrap();
    }
    inbetween_format::write_project(&dir.join("demo.inbetween"), &demo_project()).unwrap();
}

/// A scratch folder removed on drop.
struct Scratch(PathBuf);

impl Scratch {
    fn new(tag: &str) -> Self {
        let dir = std::env::temp_dir().join(format!("inbetween-cli-{tag}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        Self(dir)
    }

    fn path(&self, name: &str) -> PathBuf {
        self.0.join(name)
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn ib(args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_ib"))
        .args(args)
        .output()
        .unwrap()
}

fn stdout(o: &Output) -> String {
    String::from_utf8_lossy(&o.stdout).into_owned()
}

fn stderr(o: &Output) -> String {
    String::from_utf8_lossy(&o.stderr).into_owned()
}

fn project_arg() -> String {
    demo_dir().join("demo.inbetween").display().to_string()
}

fn max_diff(a: &[u8], b: &[u8]) -> u8 {
    assert_eq!(a.len(), b.len());
    a.iter()
        .zip(b)
        .map(|(x, y)| x.abs_diff(*y))
        .max()
        .unwrap_or(0)
}

#[test]
fn committed_demo_files_match_the_generator() {
    let dir = demo_dir();
    let (sun, moon) = demo::pair(W, H).unwrap();
    for (name, img) in [("sun.png", sun), ("moon.png", moon)] {
        let on_disk = read_file(&dir.join(name)).unwrap();
        assert_eq!(
            on_disk.data,
            img.to_rgba8(),
            "{name} is stale; regenerate the demo"
        );
    }
    let project = inbetween_format::read_project(&dir.join("demo.inbetween")).unwrap();
    assert_eq!(
        project,
        demo_project(),
        "demo.inbetween is stale; regenerate the demo"
    );
}

#[test]
fn render_writes_every_frame_and_the_ends_match_the_images() {
    let out = Scratch::new("render");
    let frames = out.path("frames");
    let o = ib(&["render", &project_arg(), "--out", frames.to_str().unwrap()]);
    assert!(o.status.success(), "{}", stderr(&o));
    assert!(
        stdout(&o).contains("Wrote 12 frames (480 x 360)"),
        "{}",
        stdout(&o)
    );

    for n in 1..=12 {
        assert!(
            frames.join(format!("frame_{n:04}.png")).exists(),
            "frame {n}"
        );
    }
    assert!(!frames.join("frame_0013.png").exists());

    let first = read_file(&frames.join("frame_0001.png")).unwrap();
    let last = read_file(&frames.join("frame_0012.png")).unwrap();
    let sun = read_file(&demo_dir().join("sun.png")).unwrap();
    let moon = read_file(&demo_dir().join("moon.png")).unwrap();
    assert!(
        max_diff(&first.data, &sun.data) <= 1,
        "first frame is not the sun"
    );
    assert!(
        max_diff(&last.data, &moon.data) <= 1,
        "last frame is not the moon"
    );

    let mid = read_file(&frames.join("frame_0006.png")).unwrap();
    assert!(max_diff(&mid.data, &sun.data) > 20 && max_diff(&mid.data, &moon.data) > 20);
}

#[test]
fn render_is_deterministic() {
    let (a, b) = (Scratch::new("det-a"), Scratch::new("det-b"));
    for s in [&a, &b] {
        let o = ib(&[
            "render",
            &project_arg(),
            "--out",
            s.path("f").to_str().unwrap(),
        ]);
        assert!(o.status.success(), "{}", stderr(&o));
    }
    for n in [1, 5, 12] {
        let name = format!("f/frame_{n:04}.png");
        assert_eq!(
            std::fs::read(a.path(&name)).unwrap(),
            std::fs::read(b.path(&name)).unwrap()
        );
    }
}

#[test]
fn frame_renders_one_image_at_a_given_time() {
    let out = Scratch::new("frame");
    let mid = out.path("mid.png");
    let o = ib(&[
        "frame",
        &project_arg(),
        "--t",
        "0.5",
        "--out",
        mid.to_str().unwrap(),
    ]);
    assert!(o.status.success(), "{}", stderr(&o));
    assert!(stdout(&o).contains("(480 x 360)"));
    let img = decode(&std::fs::read(&mid).unwrap()).unwrap();
    assert_eq!((img.width, img.height), (W, H));

    // --frame 0 is the first image; JPEG output also works.
    let first = out.path("first.jpg");
    let o = ib(&[
        "frame",
        &project_arg(),
        "--frame",
        "0",
        "--out",
        first.to_str().unwrap(),
    ]);
    assert!(o.status.success(), "{}", stderr(&o));
    assert!(decode(&std::fs::read(&first).unwrap()).is_ok());
}

#[test]
fn info_describes_the_project() {
    let o = ib(&["info", &project_arg()]);
    assert!(o.status.success(), "{}", stderr(&o));
    let t = stdout(&o);
    assert!(
        t.contains("480 x 360") && t.contains("sun to moon") && t.contains("12 frames"),
        "{t}"
    );
    assert!(
        t.contains("Image 1: sun.png") && t.contains("Image 2: moon.png"),
        "{t}"
    );

    let o = ib(&["info", &project_arg(), "--json"]);
    let v: serde_json::Value = serde_json::from_str(&stdout(&o)).unwrap();
    assert_eq!(v["sequences"][0]["dots"], 25);
    assert_eq!(v["output"]["width"], 480);
}

#[test]
fn commands_lists_everything() {
    let o = ib(&["commands"]);
    assert!(o.status.success());
    let t = stdout(&o);
    for id in [
        "project.open",
        "project.save",
        "dots.import",
        "dots.export",
        "sequence.length",
        "export.frame",
        "export.sequence",
    ] {
        assert!(t.contains(id), "{id} missing from:\n{t}");
    }
    let o = ib(&["commands", "--json"]);
    let v: serde_json::Value = serde_json::from_str(&stdout(&o)).unwrap();
    let ids: Vec<&str> = v
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|c| c["id"].as_str())
        .collect();
    assert!(ids.contains(&"export.frame"));
    let export = v
        .as_array()
        .unwrap()
        .iter()
        .find(|c| c["id"] == "export.frame")
        .unwrap();
    assert!(export["params"]
        .as_array()
        .unwrap()
        .iter()
        .any(|p| p["name"] == "out"));
}

#[test]
fn run_drives_any_command_by_id() {
    let out = Scratch::new("run");
    let dots = out.path("dots.inbetweendots");
    let o = ib(&[
        "run",
        "dots.export",
        "--project",
        &project_arg(),
        "--params",
        &format!(
            r#"{{"path": {}}}"#,
            serde_json::to_string(dots.to_str().unwrap()).unwrap()
        ),
    ]);
    assert!(o.status.success(), "{}", stderr(&o));
    let set = inbetween_format::read_dots(&dots).unwrap();
    assert_eq!(set.len(), 25);

    let o = ib(&[
        "run",
        "sequence.length",
        "--project",
        &project_arg(),
        "--params",
        r#"{"frames": 30}"#,
    ]);
    assert!(stdout(&o).contains("30"), "{}", stdout(&o));
}

#[test]
fn failures_are_clean_errors_with_a_nonzero_exit() {
    let out = Scratch::new("errors");
    let missing = out.path("missing.inbetween");
    let garbage = out.path("garbage.inbetween");
    std::fs::write(&garbage, b"\x00\xff not a project").unwrap();
    let broken_images = out.path("broken.inbetween");
    inbetween_format::write_project(&broken_images, &demo_project()).unwrap();

    let frames = out.path("frames");
    let frames = frames.to_str().unwrap();
    let cases: Vec<Vec<&str>> = vec![
        vec!["info", missing.to_str().unwrap()],
        vec!["info", garbage.to_str().unwrap()],
        vec!["render", missing.to_str().unwrap(), "--out", frames],
        // Valid project, but its images are not next to it.
        vec!["render", broken_images.to_str().unwrap(), "--out", frames],
        vec!["frame", broken_images.to_str().unwrap(), "--out", frames],
        vec!["run", "no.such.command"],
        vec!["run", "export.frame", "--params", "{not json"],
        vec!["run", "export.frame", "--params", r#"{"out": 5}"#],
        vec!["run", "sequence.length"],
    ];
    for args in cases {
        let o = ib(&args);
        assert_eq!(o.status.code(), Some(1), "{args:?}: {}", stderr(&o));
        let e = stderr(&o);
        assert!(e.starts_with("error: "), "{args:?}: {e}");
        assert!(!e.contains("panicked"), "{args:?}: {e}");
    }
}

#[test]
fn bad_time_and_usage_errors() {
    let out = Scratch::new("usage");
    let img = out.path("x.png");
    let o = ib(&[
        "frame",
        &project_arg(),
        "--t",
        "2",
        "--out",
        img.to_str().unwrap(),
    ]);
    assert_eq!(o.status.code(), Some(1));
    assert!(stderr(&o).contains("between 0 and 1"), "{}", stderr(&o));
    assert!(!img.exists());

    // --t and --frame together, and a missing --out, are usage errors (exit 2).
    let o = ib(&[
        "frame",
        &project_arg(),
        "--t",
        "0.5",
        "--frame",
        "1",
        "--out",
        "x.png",
    ]);
    assert_eq!(o.status.code(), Some(2));
    let o = ib(&["render", &project_arg()]);
    assert_eq!(o.status.code(), Some(2));
    let o = ib(&[]);
    assert_eq!(o.status.code(), Some(2));
    assert!(ib(&["--help"]).status.success());
    assert!(stdout(&ib(&["--version"])).starts_with("ib "));
}

#[test]
fn editing_through_commands_and_saving_round_trips() {
    let out = Scratch::new("edit");
    // Copy the demo so saving never touches the committed files.
    for name in ["sun.png", "moon.png", "demo.inbetween"] {
        std::fs::copy(demo_dir().join(name), out.path(name)).unwrap();
    }
    let copy = out.path("demo.inbetween");
    let copy = copy.to_str().unwrap();
    let o = ib(&[
        "run",
        "sequence.length",
        "--project",
        copy,
        "--params",
        r#"{"frames": 4}"#,
    ]);
    assert!(o.status.success(), "{}", stderr(&o));
    // `run` does not save by itself, so the file is unchanged.
    let still = inbetween_format::read_project(Path::new(copy)).unwrap();
    assert_eq!(still.sequences[0].frames, 12);

    let frames = out.path("short");
    let o = ib(&[
        "render",
        copy,
        "--out",
        frames.to_str().unwrap(),
        "--prefix",
        "shot",
    ]);
    assert!(o.status.success(), "{}", stderr(&o));
    assert!(frames.join("shot_0012.png").exists());
}

#[test]
fn render_writes_hold_frames_and_other_morph_types() {
    let out = Scratch::new("holds");
    for name in ["sun.png", "moon.png", "demo.inbetween"] {
        std::fs::copy(demo_dir().join(name), out.path(name)).unwrap();
    }
    let path = out.path("demo.inbetween");
    let mut project = inbetween_format::read_project(&path).unwrap();
    project.sequences[0].frames = 4;
    project.sequences[0].hold_start = 2;
    project.sequences[0].hold_end = 3;
    project.sequences[0].morph = inbetween_doc::MorphType::Warp2;
    inbetween_format::write_project(&path, &project).unwrap();

    let info = stdout(&ib(&["info", path.to_str().unwrap()]));
    assert!(
        info.contains("+2 hold at the start, +3 at the end"),
        "{info}"
    );

    let frames = out.path("frames");
    let o = ib(&[
        "render",
        path.to_str().unwrap(),
        "--out",
        frames.to_str().unwrap(),
    ]);
    assert!(o.status.success(), "{}", stderr(&o));
    assert!(stdout(&o).contains("Wrote 9 frames"), "{}", stdout(&o));
    let read = |n: u32| std::fs::read(frames.join(format!("frame_{n:04}.png"))).unwrap();
    assert!(!frames.join("frame_0010.png").exists());
    // Start hold repeats frame 1; end hold repeats the last morph frame; the middle differs.
    assert_eq!(read(1), read(2));
    assert_eq!(read(6), read(7));
    assert_eq!(read(7), read(9));
    assert_ne!(read(3), read(5));
}
